/* ==========================================
   Volta Studio — Global Stylesheet
   ========================================== */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-muted: #7A746D;
  --accent-terracotta: #C4725A;
  --accent-sage: #8B9E82;
  --accent-sand: #C4B39A;
  --serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --header-h: 76px;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  font-weight: 400;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

h1, h2, h3, h4 {
  font-family: var(--serif);
  font-weight: 700;
  line-height: 1.1;
}

/* --- Header --- */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-h);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 48px;
  background: rgba(245, 242, 237, 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  z-index: 1000;
}

.logo {
  font-family: var(--serif);
  font-size: 1.375rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: 40px;
  list-style: none;
}

.nav-links a {
  font-size: 0.8125rem;
  font-weight: 400;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: opacity 0.25s ease;
}

.nav-links a:hover {
  opacity: 0.5;
}

/* Hamburger */
.hamburger {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  z-index: 1002;
  width: 40px;
  height: 40px;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 1.5px;
  background: var(--text);
  transition: all 0.3s ease;
}

/* Mobile overlay */
.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.mobile-overlay nav {
  text-align: center;
}

.mobile-overlay nav a {
  display: block;
  font-family: var(--serif);
  font-size: clamp(2rem, 6vw, 3.25rem);
  font-weight: 700;
  padding: 0.35em 0;
  letter-spacing: -0.01em;
  transition: opacity 0.25s ease;
}

.mobile-overlay nav a:hover {
  opacity: 0.5;
}

.close-btn {
  position: absolute;
  top: 24px;
  right: 48px;
  background: none;
  border: none;
  font-size: 1.75rem;
  cursor: pointer;
  color: var(--text);
  line-height: 1;
  padding: 8px;
  z-index: 1003;
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .hamburger { display: flex; }
  .site-header { padding: 0 24px; }
}

/* --- Hero --- */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: flex-end;
  padding: 0 48px;
  padding-bottom: 12vh;
}

.hero h1 {
  font-size: clamp(2.75rem, 5.5vw, 4.75rem);
  max-width: 880px;
  line-height: 1.08;
  letter-spacing: -0.025em;
}

@media (max-width: 768px) {
  .hero {
    padding: 0 24px;
    padding-bottom: 10vh;
  }
  .hero h1 {
    max-width: 100%;
  }
}

/* --- Media Showcase --- */
.media-showcase {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  padding: 0 48px 100px;
}

.media-block {
  aspect-ratio: 3 / 4;
  border-radius: 3px;
}

.media-block--terracotta { background-color: var(--accent-terracotta); }
.media-block--sage { background-color: var(--accent-sage); }
.media-block--sand { background-color: var(--accent-sand); }

@media (max-width: 768px) {
  .media-showcase {
    grid-template-columns: 1fr;
    padding: 0 24px 60px;
    gap: 12px;
  }
  .media-block {
    aspect-ratio: 4 / 3;
  }
}

/* --- Client Marquee --- */
.marquee {
  padding: 56px 0;
  overflow: hidden;
  border-top: 1px solid rgba(26, 26, 26, 0.1);
  border-bottom: 1px solid rgba(26, 26, 26, 0.1);
}

.marquee-row {
  overflow: hidden;
  margin: 6px 0;
}

.marquee-track {
  display: flex;
  white-space: nowrap;
  will-change: transform;
  animation: scroll-left 36s linear infinite;
}

.marquee-track--reverse {
  animation-name: scroll-right;
  animation-duration: 42s;
}

.marquee-track--slow {
  animation-duration: 48s;
}

.marquee-item {
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3.5vw, 3rem);
  font-weight: 700;
  padding: 0 12px;
  letter-spacing: -0.01em;
  flex-shrink: 0;
}

.marquee-sep {
  padding: 0 10px;
  font-size: clamp(0.75rem, 1.5vw, 1.25rem);
  color: var(--text-muted);
  flex-shrink: 0;
  line-height: 1;
}

@keyframes scroll-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes scroll-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

@media (prefers-reduced-motion: reduce) {
  .marquee-track {
    animation-play-state: paused;
  }
}

/* --- About Section --- */
.about-section {
  padding: 140px 48px 160px;
}

.about-label {
  font-family: var(--sans);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 40px;
}

.about-text {
  max-width: 780px;
  font-size: 1.125rem;
  line-height: 1.8;
}

.about-text p {
  margin-bottom: 1.6em;
}

.about-text p:last-child {
  margin-bottom: 0;
}

@media (max-width: 768px) {
  .about-section {
    padding: 80px 24px 100px;
  }
}

/* --- Founder Letter --- */
.founder-letter {
  padding: calc(var(--header-h) + 80px) 48px 140px;
}

.letter-content {
  max-width: 660px;
  margin: 0 auto;
}

.letter-opening {
  font-family: var(--serif);
  font-size: clamp(1.75rem, 3vw, 2.25rem);
  font-weight: 700;
  line-height: 1.45;
  margin-bottom: 2.5em;
}

.letter-content p {
  font-size: 1.0625rem;
  line-height: 1.9;
  margin-bottom: 1.6em;
}

.letter-content p:last-of-type {
  margin-bottom: 0;
}

.letter-signature {
  font-family: var(--serif);
  font-size: 1.375rem;
  font-weight: 700;
  margin-top: 3em;
}

@media (max-width: 768px) {
  .founder-letter {
    padding: calc(var(--header-h) + 48px) 24px 100px;
  }
}

/* --- Philosophy --- */
.philosophy-section {
  padding: 160px 48px;
  text-align: center;
}

.philosophy-heading {
  font-size: clamp(3rem, 9vw, 7.5rem);
  letter-spacing: -0.035em;
  margin-bottom: 48px;
  line-height: 1;
}

.philosophy-text {
  max-width: 640px;
  margin: 0 auto;
  font-size: 1.125rem;
  line-height: 1.85;
}

@media (max-width: 768px) {
  .philosophy-section {
    padding: 100px 24px;
  }
}

/* --- Divider --- */
.section-divider {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 48px;
}

.section-divider hr {
  border: none;
  border-top: 1px solid rgba(26, 26, 26, 0.12);
}

@media (max-width: 768px) {
  .section-divider { padding: 0 24px; }
}

/* --- Service Details --- */
.services-section {
  padding: 120px 48px 160px;
}

.services-question {
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  font-weight: 700;
  max-width: 660px;
  margin: 0 auto 80px;
  line-height: 1.3;
  text-align: center;
}

.service-item {
  max-width: 660px;
  margin: 0 auto 56px;
}

.service-item:last-child {
  margin-bottom: 0;
}

.service-name {
  font-family: var(--serif);
  font-size: 1.375rem;
  font-weight: 700;
  margin-bottom: 14px;
  letter-spacing: -0.01em;
}

.service-desc {
  font-size: 1rem;
  line-height: 1.8;
  color: var(--text-muted);
}

@media (max-width: 768px) {
  .services-section {
    padding: 80px 24px 100px;
  }
}

/* --- Clients Grid --- */
.clients-section {
  padding: calc(var(--header-h) + 80px) 48px 160px;
}

.clients-heading {
  font-family: var(--serif);
  font-size: clamp(2rem, 4vw, 3.25rem);
  font-weight: 700;
  margin-bottom: 64px;
  letter-spacing: -0.02em;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 44px 72px;
  max-width: 1200px;
}

.client-item h3 {
  font-size: 1.1875rem;
  font-weight: 700;
  margin-bottom: 10px;
  letter-spacing: -0.01em;
}

.client-item p {
  font-size: 0.9375rem;
  line-height: 1.65;
  color: var(--text-muted);
}

@media (max-width: 1024px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 36px 48px;
  }
}

@media (max-width: 768px) {
  .clients-section {
    padding: calc(var(--header-h) + 48px) 24px 100px;
  }
  .clients-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }
}

/* --- Contact --- */
.contact-section {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 120px 48px;
  text-align: center;
}

.contact-heading {
  font-family: var(--serif);
  font-size: clamp(5rem, 18vw, 15rem);
  font-weight: 700;
  letter-spacing: -0.045em;
  line-height: 0.85;
  margin-bottom: 64px;
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: 18px;
  align-items: center;
}

.contact-links a {
  font-family: var(--serif);
  font-size: 1.25rem;
  font-weight: 700;
  transition: opacity 0.25s ease;
}

.contact-links a:hover {
  opacity: 0.5;
}

@media (max-width: 768px) {
  .contact-section {
    padding: 80px 24px;
  }
}

/* --- Footer --- */
.site-footer {
  padding: 48px;
  font-size: 0.6875rem;
  color: var(--text-muted);
  letter-spacing: 0.02em;
}

@media (max-width: 768px) {
  .site-footer { padding: 32px 24px; }
}

