/* ==========================================
   Volta Studio — Global Stylesheet
   ========================================== */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-muted: #7A746D;
  --accent-terracotta: #C4725A;
  --accent-sage: #8B9E82;
  --accent-sand: #C4B39A;
  --serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --header-h: 76px;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  font-weight: 400;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

h1, h2, h3, h4 {
  font-family: var(--serif);
  font-weight: 700;
  line-height: 1.1;
}

/* --- Header --- */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-h);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 48px;
  background: rgba(245, 242, 237, 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  z-index: 1000;
}

.logo {
  font-family: var(--serif);
  font-size: 1.375rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: 40px;
  list-style: none;
}

.nav-links a {
  font-size: 0.8125rem;
  font-weight: 400;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: opacity 0.25s ease;
}

.nav-links a:hover {
  opacity: 0.5;
}

/* Hamburger */
.hamburger {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
  z-index: 1002;
  width: 40px;
  height: 40px;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 5px;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 1.5px;
  background: var(--text);
  transition: all 0.3s ease;
}

/* Mobile overlay */
.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.mobile-overlay nav {
  text-align: center;
}

.mobile-overlay nav a {
  display: block;
  font-family: var(--serif);
  font-size: clamp(2rem, 6vw, 3.25rem);
  font-weight: 700;
  padding: 0.35em 0;
  letter-spacing: -0.01em;
  transition: opacity 0.25s ease;
}

.mobile-overlay nav a:hover {
  opacity: 0.5;
}

.close-btn {
  position: absolute;
  top: 24px;
  right: 48px;
  background: none;
  border: none;
  font-size: 1.75rem;
  cursor: pointer;
  color: var(--text);
  line-height: 1;
  padding: 8px;
  z-index: 1003;
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .hamburger { display: flex; }
  .site-header { padding: 0 24px; }
}

/* --- Hero --- */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: flex-end;
  padding: 0 48px;
  padding-bottom: 12vh;
}

.hero h1 {
  font-size: clamp(2.75rem, 5.5vw, 4.75rem);
  max-width: 880px;
  line-height: 1.08;
  letter-spacing: -0.025em;
}

@media (max-width: 768px) {
  .hero {
    padding: 0 24px;
    padding-bottom: 10vh;
  }
  .hero h1 {
    max-width: 100%;
  }
}

/* --- Media Showcase --- */
.media-showcase {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  padding: 0 48px 100px;
}

.media-block {
  aspect-ratio: 3 / 4;
  border-radius: 3px;
}

.media-block--terracotta { background-color: var(--accent-terracotta); }
.media-block--sage { background-color: var(--accent-sage); }
.media-block--sand { background-color: var(--accent-sand); }

@media (max-width: 768px) {
  .media-showcase {
    grid-template-columns: 1fr;
    padding: 0 24px 60px;
    gap: 12px;
  }
  .media-block {
    aspect-ratio: 4 / 3;
  }
}

/* --- Client Marquee --- */
.marquee {
  padding: 56px 0;
  overflow: hidden;
  border-top: 1px solid rgba(26, 26, 26, 0.1);
  border-bottom: 1px solid rgba(26, 26, 26, 0.1);
}

.marquee-row {
  overflow: hidden;
  margin: 6px 0;
}

.marquee-track {
  display: flex;
  white-space: nowrap;
  will-change: transform;
  animation: scroll-left 36s linear infinite;
}

.marquee-track--reverse {
  animation-name: scroll-right;
  animation-duration: 42s;
}

.marquee-track--slow {
  animation-duration: 48s;
}

.marquee-item {
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3.5vw, 3rem);
  font-weight: 700;
  padding: 0 12px;
  letter-spacing: -0.01em;
  flex-shrink: 0;
}

.marquee-sep {
  padding: 0 10px;
  font-size: clamp(0.75rem, 1.5vw, 1.25rem);
  color: var(--text-muted);
  flex-shrink: 0;
  line-height: 1;
}

@keyframes scroll-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes scroll-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

@media (prefers-reduced-motion: reduce) {
  .marquee-track {
    animation-play-state: paused;
  }
}

/* --- About Section --- */
.about-section {
  padding: 140px 48px 160px;
